-- Generated by execution/homework_sql.ts from docs/homework-2026-27/final/qaidah-hw1.json.
-- Loads homework 301 for 2026/27. Review, then apply with execution/apply_migration.ts.
-- Idempotent: re-running replaces the same papers again.

do $guard$ begin
  if exists (select 1 from submissions s join homeworks h on h.id = s.homework_id
             join auth.users u on u.id = s.student_id
             where h.number in (301) and coalesce(u.email, '') not like '%@bsms-demo.test') then
    raise exception 'a real student has work on a homework this load replaces; stop and ask';
  end if;
end $guard$;

-- Demo work on the replaced papers (answers, voice notes, attempts cascade).
delete from submissions where homework_id in (select id from homeworks where number in (301));
delete from questions where homework_id in (select id from homeworks where number in (301));

-- ── Homework 301: The Qur'an, Tajweed and the Letters (19 marks, 16 questions)
insert into homeworks (number, title, series, total_marks, is_graded, week_id, due_at, course_id, ordinal)
select 301, $q$The Qur'an, Tajweed and the Letters$q$, 'qaidah', 19, true, w.id, w.due_at, c.id, 1
  from weeks w, courses c where w.term_id = 1 and w.number = 1 and c.key = 'qaidah'
on conflict (number) do update set title = excluded.title, series = excluded.series, total_marks = excluded.total_marks,
  is_graded = true, course_id = excluded.course_id, ordinal = excluded.ordinal;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 1, 'text', 'exact', $q$What is the Qur'an?$q$, 1, false, false, null, $q$[{"id":"c1","desc":"It is the inimitable speech of Allah ﷻ, which was sent down to the Prophet ﷺ","marks":1}]$q$::jsonb, false
  from homeworks where number = 301;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 2, 'text', 'exact', $q$Via which medium was the Qur'an revealed to the Prophet ﷺ?$q$, 1, false, false, null, $q$[{"id":"c1","desc":"Via the Angel Jibrīl عليه السلام","marks":1}]$q$::jsonb, false
