-- Audio needs questions.media (migration 0048); skipped until it exists.
do $media$ begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'questions' and column_name = 'media') then
    update questions set media = $q${"clip":{"url":"/audio/qaidah/hw1-a.mp3","start_ms":0,"end_ms":4800}}$q$::jsonb where position = 7 and homework_id = (select id from homeworks where number = 301);
    update questions set media = $q${"clip":{"url":"/audio/qaidah/hw1-b.mp3","start_ms":0,"end_ms":4850}}$q$::jsonb where position = 8 and homework_id = (select id from homeworks where number = 301);
    update questions set media = $q${"clip":{"url":"/audio/qaidah/hw1-c.mp3","start_ms":0,"end_ms":4520}}$q$::jsonb where position = 9 and homework_id = (select id from homeworks where number = 301);
    update questions set media = $q${"clip":{"url":"/audio/qaidah/hw1-d.mp3","start_ms":0,"end_ms":5000}}$q$::jsonb where position = 10 and homework_id = (select id from homeworks where number = 301);
    update questions set media = $q${"clip":{"url":"/audio/qaidah/hw1-e.mp3","start_ms":0,"end_ms":4460}}$q$::jsonb where position = 11 and homework_id = (select id from homeworks where number = 301);
    update questions set media = $q${"clip":{"url":"/audio/qaidah/hw1-f.mp3","start_ms":0,"end_ms":4410}}$q$::jsonb where position = 12 and homework_id = (select id from homeworks where number = 301);
